// Move the Browse by category section to the very top of its parent container
const parent = element.parentElement;
if (!parent) return;
if (parent.firstElementChild === element) return; // already first
parent.insertBefore(element, parent.firstElementChild);

element.style.background = '#ffffff';
element.style.borderRadius = '12px';
element.style.padding = '24px 32px 20px';
element.style.marginBottom = '32px';
element.style.boxShadow = '0 1px 4px rgba(0,0,0,0.08)';
element.style.border = '1px solid #e9e9e9';
element.style.width = '100%';
element.style.boxSizing = 'border-box';

// Replace the masonry container with a clean text list (only once)
if (element.getAttribute('data-text-list-done') === 'true') return;

// Collect all topic rep links
const items = element.querySelectorAll('[data-test-id="interestRep"]');
if (!items || items.length === 0) return;

// Build a clean nav list
const nav = document.createElement('nav');
nav.setAttribute('aria-label', 'Browse by category');
nav.style.cssText = 'width:100%;';

const ul = document.createElement('ul');
ul.style.cssText = [
  'list-style: none',
  'margin: 0',
  'padding: 0',
  'display: grid',
  'grid-template-columns: repeat(auto-fill, minmax(160px, 1fr))',
  'gap: 4px 8px'
].join(';');

items.forEach(item => {
  const anchor = item.querySelector('a');
  const titleEl = item.querySelector('[data-test-id="topic-rep-title"]');
  if (!anchor || !titleEl) return;

  const text = titleEl.getAttribute('title') || titleEl.textContent.trim();
  if (!text) return;

  const li = document.createElement('li');
  li.style.cssText = 'margin:0;padding:0;';

  const a = document.createElement('a');
  a.href = anchor.href;
  a.textContent = text;
  a.style.cssText = [
    'display: flex',
    'align-items: center',
    'padding: 9px 14px',
    'border-radius: 8px',
    'text-decoration: none',
    'font-size: 14px',
    'font-weight: 600',
    'color: #111111',
    'background: #f8f8f8',
    'transition: background 0.15s, color 0.15s',
    'white-space: nowrap',
    'overflow: hidden',
    'text-overflow: ellipsis',
    'gap: 8px'
  ].join(';');

  // Small arrow indicator
  const arrow = document.createElement('span');
  arrow.textContent = '›';
  arrow.style.cssText = 'margin-left:auto;font-size:16px;color:#767676;flex-shrink:0;';
  a.appendChild(arrow);

  a.addEventListener('mouseover', function() {
    this.style.background = '#e60023';
    this.style.color = '#ffffff';
    arrow.style.color = '#ffffff';
  });
  a.addEventListener('mouseout', function() {
    this.style.background = '#f8f8f8';
    this.style.color = '#111111';
    arrow.style.color = '#767676';
  });

  li.appendChild(a);
  ul.appendChild(li);
});

nav.appendChild(ul);

// Replace the masonry container content with the new list
element.innerHTML = '';
element.style.cssText = 'width:100%;';
element.appendChild(nav);
element.setAttribute('data-text-list-done', 'true');

element.style.fontSize = '20px';
element.style.fontWeight = '700';
element.style.color = '#111111';
element.style.marginBottom = '16px';
element.style.marginTop = '0';
element.style.letterSpacing = '-0.2px';
